import{_ as o,o as i,c as s,ag as n}from"./chunks/framework.4Y_9FogC.js";const a="/videos/Theengs-app-demo.mp4",r="/assets/Theengs-app-threshold-settings.C1qmJbpV.png",l="/assets/Theengs-app-threshold-settings-default.BQKQEQss.png",c="/assets/Theengs-app-live-monitoring.yePKE5Js.png",d="/videos/Theengs-App-mqtt-integration.mp4",h="/assets/Theengs-set-mac.DCXySRqj.png",p="/assets/Theengs_app_auto_discovery_BLE_Sensor_Home_Assistant.DoJJlpeV.gif",u="/assets/Theengs-app-location-permission-8.D5ahQ_jQ.png",g="/assets/Theengs-app-battery-excluded.Q2kpxB-e.png",t="/assets/Theengs-app-background-updates.BqHcQEkI.png",m="/assets/Theengs-app-location-permission.Dlfr6ybi.png",b="/assets/Theengs-app-nearby-permission.C-KMARDB.png",f="/assets/Theengs-app-unused-permission.rABoNYfU.png",y="/assets/Theengs-app-battery.BD83D9SR.png",v="/assets/Theengs-app-battery-unrestricted.CtLGhLYE.png",A=JSON.parse('{"title":"Use","description":"","frontmatter":{},"headers":[],"relativePath":"use/use.md","filePath":"use/use.md","lastUpdated":1780765817000}'),k={name:"use/use.md"};function w(T,e,q,B,S,_){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="use" tabindex="-1">Use <a class="header-anchor" href="#use" aria-label="Permalink to &quot;Use&quot;">​</a></h1><h2 id="features-comparison-between-operating-systems" tabindex="-1">Features comparison between Operating Systems <a class="header-anchor" href="#features-comparison-between-operating-systems" aria-label="Permalink to &quot;Features comparison between Operating Systems&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">OS</th><th style="text-align:center;">Real time data</th><th style="text-align:center;">BBQ monitoring</th><th style="text-align:center;">Battery monitors</th><th style="text-align:center;">SwitchBot control</th><th style="text-align:center;">MQTT integration (incl. TLS)</th><th style="text-align:center;">Running in background</th><th style="text-align:center;">Home Assistant Auto Discovery</th></tr></thead><tbody><tr><td style="text-align:center;">iOS</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;"></td><td style="text-align:center;">☑️</td></tr><tr><td style="text-align:center;">Android</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️</td><td style="text-align:center;">☑️ <em>(foreground service)</em></td><td style="text-align:center;">☑️</td></tr></tbody></table><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><video width="353" height="628" controls><source src="'+a+'" type="video/mp4"> Your browser does not support the video tag. </video><h2 id="real-time-data" tabindex="-1">Real time data <a class="header-anchor" href="#real-time-data" aria-label="Permalink to &quot;Real time data&quot;">​</a></h2><p>The app enables to retrieve BLE sensor real time data, to add new sensors tap &quot;Search for new sensors&quot; in the hamburger menu.</p><p>To refresh the sensor data tap &quot;Refresh sensor data&quot; in the hamburger menu.</p><p>History charts on each device screen show the sampling interval used for the displayed data as a caption underneath the chart, so values from sparsely-broadcasting sensors can be interpreted at a glance.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Why does Theengs App needs the location permission?</p><p>Theengs App requires the location permission to access your device Bluetooth and retrieves sensor data. Theengs is not accessing your location with GPS/GLONASS/BAIDU.</p></div><h2 id="live-bbq-monitoring" tabindex="-1">Live BBQ monitoring <a class="header-anchor" href="#live-bbq-monitoring" aria-label="Permalink to &quot;Live BBQ monitoring&quot;">​</a></h2><h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h3><p>Live BBQ Monitoring allows you to track the temperature of your grill in real time, ensuring perfect cooking results. The feature includes different Threshold Settings, a Live Chart, and Notifications for comprehensive monitoring. This feature requires staying on the BBQ sensor screen to function effectively.</p><h3 id="compatible-devices" tabindex="-1">Compatible devices <a class="header-anchor" href="#compatible-devices" aria-label="Permalink to &quot;Compatible devices&quot;">​</a></h3><p>This feature is compatible with the following devices:</p><ul><li>Govee H5055</li><li>Inkbird IBT-2X(S)</li><li>Inkbird IBT-4X(S/C)</li><li>Inkbird IBT-6X(S)</li><li>SOLIS_6</li></ul><h3 id="threshold-settings" tabindex="-1">Threshold settings <a class="header-anchor" href="#threshold-settings" aria-label="Permalink to &quot;Threshold settings&quot;">​</a></h3><p>Access the threshold settings from the hamburger menu.</p><p><img src="'+r+'" alt="Threshold settings"></p><p>Select &#39;+&#39; to customize temperature ranges for different meats or cooking stages.</p><p><img src="'+l+'" alt="Threshold settings choice"></p><p>Name your preset for easy identification, e.g., &#39;Poultry&#39;, &#39;Rare Steak&#39;. Enter your desired temperature range. You can modify these presets anytime.</p><p>From the BBQ sensor view you can select the presets of your choice.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The cooking temperatures provided in this app are general recommendations. Variations in equipment, ingredients, and conditions can affect cooking outcomes. Always verify food is cooked to safe temperatures. The application developer is not liable for any cooking results.</p></div><h3 id="live-monitoring" tabindex="-1">Live monitoring <a class="header-anchor" href="#live-monitoring" aria-label="Permalink to &quot;Live monitoring&quot;">​</a></h3><p>The Live Chart displays live temperature data from your BBQ sensor. To view, tap on your BBQ device from the main screen. The chart shows temperature changes over time, helping you monitor the cooking process.</p><p><img src="'+c+'" alt="Live monitoring"></p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><p>Enable notifications when prompted. Your phone must not be in silent or do not disturb mode. Set temperature thresholds based on your meal. When the sensor detects temperatures beyond this range, you&#39;ll receive an alert.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>For continuous monitoring and notifications, you must keep the app open on the BBQ sensor screen. Update frequency and real-time responsiveness depend on your smartphone’s processing capabilities, not the app. For best results, close unnecessary apps and ensure you are not far from the sensor.</p></div><h2 id="battery-monitors" tabindex="-1">Battery monitors <a class="header-anchor" href="#battery-monitors" aria-label="Permalink to &quot;Battery monitors&quot;">​</a></h2><p>Theengs App supports a dedicated <strong>Battery monitor</strong> device class for 12 V lead-acid / LiFePO4 monitoring dongles:</p><ul><li><strong>BM2</strong> — voltage broadcast on advertisement, plus connection-based history retrieval.</li><li><strong>BM6</strong> — voltage, temperature, and state-of-charge.</li></ul><p>The battery-monitor screen shows the live voltage with a 0–20 V scale, a rolling chart, and configurable <strong>battery presets</strong> (chemistry / nominal voltage / warning thresholds) reachable from the hamburger menu — similar to BBQ threshold presets.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>On iOS the BM6 requires a one-time detection handshake. The app handles this automatically the first time the device is added; just keep the dongle in range.</p></div><h2 id="switchbot-control" tabindex="-1">SwitchBot control <a class="header-anchor" href="#switchbot-control" aria-label="Permalink to &quot;SwitchBot control&quot;">​</a></h2><p>Beyond reading sensors, Theengs App can <strong>control</strong> several SwitchBot actuators over BLE. Control is connection-based: the app pairs to the device on demand, sends the action, then releases the link.</p><h3 id="supported-switchbot-devices" tabindex="-1">Supported SwitchBot devices <a class="header-anchor" href="#supported-switchbot-devices" aria-label="Permalink to &quot;Supported SwitchBot devices&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Device</th><th>Model ID</th><th>Actions</th></tr></thead><tbody><tr><td>SwitchBot Bot S1 / SmartSwitch</td><td><code>SBS1</code> (alias <code>X1</code>)</td><td>On, Off, Push-Pull, with selectable <strong>Press</strong> / <strong>Switch</strong> mode, inverted-direction toggle, and configurable press duration</td></tr><tr><td>SwitchBot Curtain 2 / Curtain 3</td><td><code>SBCU</code> (alias <code>W070160X</code>)</td><td>Open, Close, Stop, move to position (0–100 %), High / Low speed</td></tr><tr><td>SwitchBot Blind Tilt</td><td><code>SBBT</code> (alias <code>W270160X</code>)</td><td>Open, Close up, Close down, Stop, tilt to position (-100…100 %)</td></tr></tbody></table><h3 id="how-to-use" tabindex="-1">How to use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to use&quot;">​</a></h3><ol><li>Wake the device once (press the button on the Bot, or the sync button under the Curtain / Blind Tilt) so it advertises.</li><li>In Theengs App, <strong>Search for new sensors</strong> — the SwitchBot device appears as an actuator with a dedicated screen.</li><li>Tap the device tile to open the control screen and use the dedicated buttons or position slider.</li></ol><p>The Bot S1 lets you switch between <strong>Press</strong> mode (one-shot push) and <strong>Switch</strong> mode (latching on/off) from the same screen, and supports an <em>invert direction</em> toggle if your physical setup expects the opposite movement.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Each control requires a brief BLE connection to the SwitchBot device, so the action may take a second or two. Battery level is read back from advertisements when available.</p></div><h2 id="mqtt-integration" tabindex="-1">MQTT integration <a class="header-anchor" href="#mqtt-integration" aria-label="Permalink to &quot;MQTT integration&quot;">​</a></h2><p>Prerequisites:</p><ul><li>MQTT broker setup in your local network (Mosquitto is a well known broker)</li></ul><p>Theengs app can publish the data to an MQTT broker, to do so go to the hamburger menu, select Integration. Enter the following informations:</p><ul><li>Broker host IP (compulsory)</li><li>Broker port (compulsory, default: <code>1883</code>)</li><li>Username (optional)</li><li>Password (optional)</li><li>Topic (compulsory, default: <code>home</code>)</li><li>SubTopic (compulsory, default: <code>TheengsApp</code>)</li></ul><p>Once done click on the MQTT switch to activate the integration, if the app can connect to the broker, it will display &quot;Connected&quot; in the top right.</p><video width="353" height="767" controls><source src="'+d+'" type="video/mp4"> Your browser does not support the video tag. </video><h3 id="tls-encrypted-brokers" tabindex="-1">TLS-encrypted brokers <a class="header-anchor" href="#tls-encrypted-brokers" aria-label="Permalink to &quot;TLS-encrypted brokers&quot;">​</a></h3><p>Theengs app can connect to MQTT brokers over TLS, including HiveMQ Cloud and other public-CA brokers as well as private brokers with self-signed certificates. From the Integration screen, in the <strong>Options</strong> section:</p><ul><li>Toggle <strong>Use TLS</strong> on. The default port <code>1883</code> is plaintext — TLS brokers usually listen on port <code>8883</code>, the app shows an inline hint to change it when needed.</li><li>For brokers using a public CA (HiveMQ Cloud, AWS IoT, etc.) leave the <strong>Custom CA certificate</strong> field empty — the system root CA store is used automatically.</li><li>For private / self-signed brokers, tap the folder icon in the <strong>Custom CA certificate</strong> field to browse and pick a CA <code>.pem</code> (or <code>.crt</code>/<code>.cer</code>/<code>.der</code>) file from Files / iCloud Drive (iOS) or local storage (Android/desktop).</li><li>If the broker uses a self-signed cert that doesn&#39;t match its hostname and you trust the network, toggle <strong>Skip validation</strong> on. A red warning is shown when this is enabled — only use it with brokers you control. Tap the (i) icon next to the toggle to collapse the warning once acked.</li></ul><p>The bottom <strong>Activity</strong> panel shows timestamped status changes and TLS handshake errors so you can diagnose connection problems. The buffer is capped at the 100 most-recent entries.</p><h3 id="ios-specificity" tabindex="-1">iOS specificity <a class="header-anchor" href="#ios-specificity" aria-label="Permalink to &quot;iOS specificity&quot;">​</a></h3><p>If you want to push data to an MQTT broker you will need to manually enter a MAC address for the sensor, this is done from the sensor page see below:</p><p><img src="'+h+'" alt="add-mac"></p><h3 id="home-assistant-auto-discovery" tabindex="-1">Home Assistant Auto Discovery <a class="header-anchor" href="#home-assistant-auto-discovery" aria-label="Permalink to &quot;Home Assistant Auto Discovery&quot;">​</a></h3><p>Theengs app can publish your sensor definition following Home Assistant MQTT convention, so as to do this you need to activate “Enable discovery” into your MQTT Options and follow the steps below:</p><p><img src="'+p+'" alt="location"></p><p>The sensor definition will be publish when the app connect to the broker. You can retrigger the publication by deactivating and reactivating the MQTT integration from the application.</p><h2 id="ios-permissions" tabindex="-1">iOS permissions <a class="header-anchor" href="#ios-permissions" aria-label="Permalink to &quot;iOS permissions&quot;">​</a></h2><p>The application will ask you for permission to use Bluetooth. You can learn more on Apple <a href="https://support.apple.com/HT210578" target="_blank" rel="noreferrer">website</a>.</p><h2 id="android-permissions" tabindex="-1">Android permissions <a class="header-anchor" href="#android-permissions" aria-label="Permalink to &quot;Android permissions&quot;">​</a></h2><p>The Android operating system requires applications to ask for device location permission in order to scan for nearby Bluetooth Low Energy sensors. You would need to go into the app information (long press on the icon -&gt; (i)) so as to configure the app permissions properly.</p><h3 id="android-8" tabindex="-1">Android 8+ <a class="header-anchor" href="#android-8" aria-label="Permalink to &quot;Android 8+&quot;">​</a></h3><ul><li>Click on Permissions</li><li>Activate &quot;your location&quot;</li></ul><p><img src="'+u+'" alt="location"></p><p>You can now use the application. If you want to run the application in the background follow the process below:</p><ul><li>Go back</li><li>Click on &quot;Battery&quot;</li><li>Click on &quot;Power saving exclusions&quot;</li><li>Activate the exclusion for Theengs</li></ul><p><img src="'+g+'" alt="location"></p><ul><li>And finally go into the app settings and toggle &quot;Enable background updates&quot;</li></ul><p><img src="'+t+'" alt="background"></p><h3 id="android-10" tabindex="-1">Android 10+ <a class="header-anchor" href="#android-10" aria-label="Permalink to &quot;Android 10+&quot;">​</a></h3><h4 id="running-when-displayed-only" tabindex="-1">Running when displayed only <a class="header-anchor" href="#running-when-displayed-only" aria-label="Permalink to &quot;Running when displayed only&quot;">​</a></h4><ul><li>Click on Permissions</li><li>Click on Location permission</li><li>Select &quot;Allow only while using the app&quot;, if you want the app to update sensors data only when the app is running at the front</li><li>Enable &quot;Use precise location&quot; if you have this option</li></ul><h4 id="running-in-the-background-foreground-service" tabindex="-1">Running in the background (foreground service) <a class="header-anchor" href="#running-in-the-background-foreground-service" aria-label="Permalink to &quot;Running in the background (foreground service)&quot;">​</a></h4><p>To keep scanning when the screen is off, Theengs App starts a <strong>foreground BLE-scan service</strong> with a persistent notification. The notification doubles as a live status panel: it shows the most recent reading and, if MQTT is enabled, the connection state and a drop counter when publishes fail.</p><p>To enable it:</p><ul><li>Click on &quot;Permissions&quot;</li><li>Click on &quot;Location&quot; → &quot;Allow all the time&quot;, and enable &quot;Use precise location&quot;</li></ul><p><img src="'+m+'" alt="location"></p><ul><li>Go back, click on &quot;Nearby devices&quot; → &quot;Allow&quot;</li></ul><p><img src="'+b+'" alt="nearby"></p><ul><li>On first launch the app will request the <strong>Notifications</strong> permission — accept it; the foreground service relies on the persistent notification being visible.</li><li>Go back twice and deactivate &quot;Remove permissions if app is unused&quot;</li></ul><p><img src="'+f+'" alt="unused"></p><ul><li>Click on battery</li></ul><p><img src="'+y+'" alt="battery"></p><ul><li>Select unrestricted</li></ul><p><img src="'+v+'" alt="unrestricted"></p><ul><li>Finally, in the app settings, toggle &quot;Enable background updates&quot;</li></ul><p><img src="'+t+'" alt="background"></p><p>Some devices also require the GPS to be turned on while scanning for new sensors.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>Even with the foreground service, Android may still throttle scanning when the device is in deep doze. Results are most consistent when the phone is charging or the screen is on. The notification is required by Android for any long-running BLE foreground task; dismissing it stops the background scan.</p></div>',93)])])}const P=o(k,[["render",w]]);export{A as __pageData,P as default};
